import{_ as t,C as l,o as e,c as n,a2 as o,b as c,w as r,a as d,E as s,a3 as u}from"./chunks/framework.CgxQ0r6v.js";const y=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 4","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-X/Lectura_Catedra_Evaluacion_4.md","filePath":"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-X/Lectura_Catedra_Evaluacion_4.md"}'),p={name:"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-X/Lectura_Catedra_Evaluacion_4.md"};function m(f,a,P,g,C,A){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="manual-de-estudio-profundo-evaluacion-4" tabindex="-1">Manual de Estudio Profundo: Evaluación 4 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-4" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 4&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-iv-trayecto-iv-trimestre-x" tabindex="-1">Materia: Proyecto Sociotecnológico IV (Trayecto IV - Trimestre X) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-iv-trayecto-iv-trimestre-x" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico IV (Trayecto IV - Trimestre X)&quot;">​</a></h2><h3 id="eje-tematico-formulacion-y-defensa-de-la-propuesta-de-trabajo-especial-de-grado" tabindex="-1">Eje Temático: Formulación y Defensa de la Propuesta de Trabajo Especial de Grado <a class="header-anchor" href="#eje-tematico-formulacion-y-defensa-de-la-propuesta-de-trabajo-especial-de-grado" aria-label="Permalink to &quot;Eje Temático: Formulación y Defensa de la Propuesta de Trabajo Especial de Grado&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-aprobacion-del-proyecto-de-grado-de-ingenieria" tabindex="-1">🧭 Introducción: La Aprobación del Proyecto de Grado de Ingeniería <a class="header-anchor" href="#🧭-introduccion-la-aprobacion-del-proyecto-de-grado-de-ingenieria" aria-label="Permalink to &quot;🧭 Introducción: La Aprobación del Proyecto de Grado de Ingeniería&quot;">​</a></h2><p>La Evaluación 4 del Trimestre X marca un punto de no retorno: <strong>la presentación y defensa formal de la Propuesta de Trabajo Especial de Grado</strong> ante el Comité Técnico de Investigación de la UPTT &quot;Mario Briceño Iragorry&quot;.</p><p>En esta instancia, los jurados no evalúan intenciones ni ideas sueltas; evalúan un proyecto de ingeniería completamente formulado, delimitado, justificado, presupuestado y planificado con rigor metodológico, cuya aprobación otorga el aval formal para iniciar la construcción en el Trimestre XI.</p><hr><h2 id="📑-capitulo-i-estructura-oficial-de-la-propuesta-de-grado" tabindex="-1">📑 CAPÍTULO I: Estructura Oficial de la Propuesta de Grado <a class="header-anchor" href="#📑-capitulo-i-estructura-oficial-de-la-propuesta-de-grado" aria-label="Permalink to &quot;📑 CAPÍTULO I: Estructura Oficial de la Propuesta de Grado&quot;">​</a></h2><p>La propuesta escrita de PST IV se rige por las directrices del Reglamento de Proyectos Sociotecnológicos de la UPTT:</p>',10)),(e(),c(u,null,{default:r(()=>[s(i,{id:"mermaid-26",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20PROP%5B%22%F0%9F%93%91%20Propuesta%20de%20Trabajo%20de%20Grado%20(PST%20IV)%22%5D%0A%20%20%20%20PROP%20--%3E%20P1%5B%221.%20Datos%20Institucionales%2C%20T%C3%ADtulo%20Preliminar%20y%20Datos%20del%20Equipo%22%5D%0A%20%20%20%20PROP%20--%3E%20P2%5B%222.%20El%20Problema%3A%20Contexto%2C%20Planteamiento%2C%20%C3%81rbol%20EML%20y%20Objetivos%22%5D%0A%20%20%20%20PROP%20--%3E%20P3%5B%223.%20Justificaci%C3%B3n%20e%20Impacto%3A%20Social%2C%20Tecnol%C3%B3gico%2C%20Econ%C3%B3mico%20y%20Legal%22%5D%0A%20%20%20%20PROP%20--%3E%20P4%5B%224.%20Marco%20Metodol%C3%B3gico%3A%20Metodolog%C3%ADa%20de%20Software%20e%20Infraestructura%22%5D%0A%20%20%20%20PROP%20--%3E%20P5%5B%225.%20Plan%20de%20Calidad%20(ISO%2025010)%20y%20Factibilidad%20(COCOMO%20II)%22%5D%0A%20%20%20%20PROP%20--%3E%20P6%5B%226.%20Cronograma%20de%20Gantt%20y%20Ruta%20Cr%C3%ADtica%20(CPM%20%2F%20PERT)%22%5D%0A%0A%20%20%20%20style%20PROP%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20P1%20fill%3A%23475569%2Cstroke%3A%2394a3b8%2Ccolor%3A%23fff%0A%20%20%20%20style%20P2%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20P3%20fill%3A%231e3a8a%2Cstroke%3A%233b82f6%2Ccolor%3A%23fff%0A%20%20%20%20style%20P4%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A%20%20%20%20style%20P5%20fill%3A%237c2d12%2Cstroke%3A%23ea580c%2Ccolor%3A%23fff%0A%20%20%20%20style%20P6%20fill%3A%23b45309%2Cstroke%3A%23f59e0b%2Ccolor%3A%23fff%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h3 id="_1-1-el-titulo-del-proyecto-de-ingenieria" tabindex="-1">1.1 El Título del Proyecto de Ingeniería <a class="header-anchor" href="#_1-1-el-titulo-del-proyecto-de-ingenieria" aria-label="Permalink to &quot;1.1 El Título del Proyecto de Ingeniería&quot;">​</a></h3><p>El título debe ser preciso y responder a la fórmula: $$\\text{[Acción en Infinitivo]} + \\text{[Solución Tecnológica Integral]} + \\text{[Objeto / Proceso]} + \\text{[Institución u Organización]} + \\text{[Ubicación Geográfica]}$$</p><ul><li><em>Ejemplo correcto:</em> <em>&quot;Desarrollo e Implantación de un Sistema de Información y Monitoreo Telemétrico en Software Libre para la Gestión del Almacén Central del Hospital Universitario &#39;Dr. Pedro Emilio Carrillo&#39;, Valera, Estado Trujillo.&quot;</em></li></ul><hr><h2 id="⏱️-capitulo-ii-planificacion-temporal-avanzada-wbs-y-ruta-critica-cpm" tabindex="-1">⏱️ CAPÍTULO II: Planificación Temporal Avanzada: WBS y Ruta Crítica (CPM) <a class="header-anchor" href="#⏱️-capitulo-ii-planificacion-temporal-avanzada-wbs-y-ruta-critica-cpm" aria-label="Permalink to &quot;⏱️ CAPÍTULO II: Planificación Temporal Avanzada: WBS y Ruta Crítica (CPM)&quot;">​</a></h2><p>A nivel de ingeniería, el cronograma de Gantt debe complementarse con la <strong>Ruta Crítica (Critical Path Method - CPM)</strong>:</p><ul><li>Identifica la secuencia de actividades dependientes que determinan la duración mínima total del proyecto.</li><li>Cualquier retraso en una actividad de la ruta crítica (ej: aprobación del modelo de base de datos o compra de un sensor) retrasa automáticamente la fecha de graduación de los estudiantes.</li></ul><hr><h2 id="🎤-capitulo-iii-el-protocolo-de-la-defensa-oral-de-la-propuesta" tabindex="-1">🎤 CAPÍTULO III: El Protocolo de la Defensa Oral de la Propuesta <a class="header-anchor" href="#🎤-capitulo-iii-el-protocolo-de-la-defensa-oral-de-la-propuesta" aria-label="Permalink to &quot;🎤 CAPÍTULO III: El Protocolo de la Defensa Oral de la Propuesta&quot;">​</a></h2><p>La defensa se realiza en sesión académica formal ante tres docentes examinadores:</p><ol><li><strong>Presentación con Diapositivas (15 minutos):</strong><ul><li>Problema real evidenciado con datos cuantitativos.</li><li>Solución propuesta: arquitectura de hardware, red y software libre.</li><li>Métricas de calidad y viabilidad económica/legal.</li><li>Cronograma detallado de los Trimestres XI y XII.</li></ul></li><li><strong>Ciclo de Preguntas y Veredicto (10 minutos):</strong><ul><li>El jurado puede dictaminar: <strong>Aprobada sin modificaciones</strong>, <strong>Aprobada con observaciones menores</strong> (plazo de 7 días para consignar correcciones) o <strong>Rechazada por inviabilidad técnica o metodológica</strong>.</li></ul></li></ol><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-4" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 4 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-4" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 4&quot;">​</a></h2><p>Para superar la Evaluación 4 y cerrar el Trimestre X:</p><ol><li><strong>Documento de la Propuesta de Grado Encuadernado y Digital:</strong> Con firmas y sellos de la organización y los tutores.</li><li><strong>Acta de Aprobación de la Propuesta:</strong> Emitida y firmada por el jurado evaluador institucional.</li><li><strong>Cronograma Oficial de Ejecución:</strong> Con hitos de control de versiones y entregas de sprints para el Trimestre XI.</li></ol>',15))])}const h=t(p,[["render",m]]);export{y as __pageData,h as default};
